#include <vector>
#include <algorithm>

class Solution {
public:
    bool hasIncreasingSubarrays(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (2 * k > n) return false;

        std::vector<int> runs;
        int curr = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) {
                curr++;
            } else {
                runs.push_back(curr);
                curr = 1;
            }
        }
        runs.push_back(curr);

        for (int L : runs) {
            if (L >= 2 * k) return true;
        }
        for (int i = 0; i < (int)runs.size() - 1; ++i) {
            if (runs[i] >= k && runs[i + 1] >= k) return true;
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean hasIncreasingSubarrays(List<Integer> nums, int k) {
        int n = nums.size();
        if (2 * k > n) return false;

        List<Integer> runs = new ArrayList<>();
        int curr = 1;
        for (int i = 1; i < n; i++) {
            if (nums.get(i) > nums.get(i - 1)) {
                curr++;
            } else {
                runs.add(curr);
                curr = 1;
            }
        }
        runs.add(curr);

        for (int L : runs) {
            if (L >= 2 * k) return true;
        }
        for (int i = 0; i < runs.size() - 1; i++) {
            if (runs.get(i) >= k && runs.get(i + 1) >= k) return true;
        }
        return false;
    }
}

